"use client";

import {
  useEffect,
  useMemo,
  useRef,
  useState,
  useCallback,
} from "react";
import { motion } from "framer-motion";
import useDesktopMotion from "../ui/useDesktopMotion";

import Lightbox from "yet-another-react-lightbox";
import "yet-another-react-lightbox/styles.css";
import Fullscreen from "yet-another-react-lightbox/plugins/fullscreen";
import Zoom from "yet-another-react-lightbox/plugins/zoom";

type CategoryItem = {
  title: string;
  material: string;
  image: string;
};

type Category = {
  id: string;
  title: string;
  description: string;
  items: CategoryItem[];
};

type PortfolioProps = {
  categories: Category[];
};

export default function Portfolio({ categories }: PortfolioProps) {
  const [activeCategory, setActiveCategory] = useState("all");
  const sliderRef = useRef<HTMLDivElement | null>(null);

  const { isMounted, shouldAnimate } = useDesktopMotion();

  /* ---------------- Lightbox ---------------- */

  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);

  const lastViewRef = useRef<{
    activeCategory: string;
    scrollLeft: number;
  } | null>(null);

  /* ---------------- Desktop scroll hints ---------------- */

  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(false);

  const updateScrollHints = useCallback(() => {
    const el = sliderRef.current;
    if (!el) return;

    const max = Math.max(0, el.scrollWidth - el.clientWidth);
    const left = el.scrollLeft;
    const eps = 8;

    setCanScrollLeft(left > eps);
    setCanScrollRight(left < max - eps);
  }, []);

  const scrollByStep = useCallback((direction: -1 | 1) => {
    const el = sliderRef.current;
    if (!el) return;

    const step = Math.round(el.clientWidth * 0.85);
    el.scrollBy({ left: direction * step, behavior: "smooth" });
  }, []);

  /* ---------------- Data ---------------- */

  const activeCategoryData = useMemo(
    () => categories.find((c) => c.id === activeCategory),
    [activeCategory, categories]
  );

  const visibleItems = useMemo(() => {
    if (activeCategory === "all") {
      return categories.flatMap((c) => c.items);
    }
    return activeCategoryData?.items ?? [];
  }, [activeCategory, activeCategoryData, categories]);

  const slides = useMemo(
    () =>
      visibleItems.map((item) => ({
        src: item.image,
        alt: item.title,
        title: item.title,
        description: item.material,
      })),
    [visibleItems]
  );

  /* ---------------- Animations ---------------- */

  const fadeUp = (delay = 0) =>
    shouldAnimate
      ? {
          initial: { opacity: 0, y: 20 },
          whileInView: { opacity: 1, y: 0 },
          transition: { duration: 0.6, ease: "easeOut", delay },
          viewport: { once: true, amount: 0.3 },
        }
      : { initial: false };

  const fadeUpProps = (delay = 0) => (isMounted ? fadeUp(delay) : {});

  /* ---------------- Lightbox handlers ---------------- */

  const openLightbox = useCallback(
    (index: number) => {
      lastViewRef.current = {
        activeCategory,
        scrollLeft: sliderRef.current?.scrollLeft ?? 0,
      };

      setLightboxIndex(index);
      setIsLightboxOpen(true);

      if (typeof window !== "undefined") {
        window.history.pushState({ portfolioLightbox: true }, "");
      }
    },
    [activeCategory]
  );

  const closeLightbox = useCallback((opts?: { viaPopState?: boolean }) => {
    setIsLightboxOpen(false);

    if (typeof window !== "undefined" && !opts?.viaPopState) {
      if (window.history.state?.portfolioLightbox) {
        window.history.back();
      }
    }

    const snap = lastViewRef.current;
    if (snap) {
      setActiveCategory(snap.activeCategory);
      requestAnimationFrame(() => {
        sliderRef.current?.scrollTo({
          left: snap.scrollLeft,
          behavior: "auto",
        });
      });
    }
  }, []);

  useEffect(() => {
    const onPopState = () => {
      if (isLightboxOpen) {
        closeLightbox({ viaPopState: true });
      }
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, [isLightboxOpen, closeLightbox]);

  /* ---------------- Scroll listeners ---------------- */

  useEffect(() => {
    updateScrollHints();
    const el = sliderRef.current;
    if (!el) return;

    el.addEventListener("scroll", updateScrollHints, { passive: true });
    const ro = new ResizeObserver(updateScrollHints);
    ro.observe(el);

    return () => {
      el.removeEventListener("scroll", updateScrollHints);
      ro.disconnect();
    };
  }, [updateScrollHints]);

  /* ---------------- Existing drag / wheel logic (unchanged) ---------------- */

  useEffect(() => {
    const slider = sliderRef.current;
    if (!slider || typeof window === "undefined") return;

    const mediaQuery = window.matchMedia("(min-width: 1024px)");
    const dragThreshold = 6;
    let isPointerDown = false;
    let isDragging = false;
    let startX = 0;
    let startScrollLeft = 0;

    const handleMouseDown = (e: MouseEvent) => {
      if (!mediaQuery.matches || e.button !== 0) return;
      isPointerDown = true;
      isDragging = false;
      startX = e.pageX;
      startScrollLeft = slider.scrollLeft;
    };

    const handleMouseMove = (e: MouseEvent) => {
      if (!mediaQuery.matches || !isPointerDown) return;
      const delta = e.pageX - startX;
      if (!isDragging && Math.abs(delta) > dragThreshold) {
        isDragging = true;
        slider.classList.add("is-dragging");
      }
      if (!isDragging) return;
      e.preventDefault();
      slider.scrollLeft = startScrollLeft - delta;
    };

    const endDrag = () => {
      isPointerDown = false;
      isDragging = false;
      slider.classList.remove("is-dragging");
    };

    slider.addEventListener("mousedown", handleMouseDown);
    slider.addEventListener("mousemove", handleMouseMove);
    slider.addEventListener("mouseup", endDrag);
    slider.addEventListener("mouseleave", endDrag);

    return () => {
      slider.removeEventListener("mousedown", handleMouseDown);
      slider.removeEventListener("mousemove", handleMouseMove);
      slider.removeEventListener("mouseup", endDrag);
      slider.removeEventListener("mouseleave", endDrag);
    };
  }, []);

  /* ---------------- Render ---------------- */

  return (
    <section className="portfolio-section bg-cream-light py-16 sm:py-20">
      <motion.div {...fadeUpProps(0)}>
        <div className="section-header">
          <h2 className="section-title">Наши работы</h2>
        </div>
      </motion.div>

      <motion.div {...fadeUpProps(0.1)} className="mt-10">
        <div className="relative">
          {/* gradients */}
          <div
            aria-hidden
            className={`pointer-events-none absolute inset-y-0 left-0 z-10 w-14 bg-gradient-to-r from-cream-light to-transparent transition-opacity ${
              canScrollLeft ? "opacity-100" : "opacity-0"
            }`}
          />
          <div
            aria-hidden
            className={`pointer-events-none absolute inset-y-0 right-0 z-10 w-14 bg-gradient-to-l from-cream-light to-transparent transition-opacity ${
              canScrollRight ? "opacity-100" : "opacity-0"
            }`}
          />

          {/* arrows */}
          <button
            type="button"
            onClick={() => scrollByStep(-1)}
            aria-label="Влево"
            className={`hidden lg:flex absolute left-2 top-1/2 -translate-y-1/2 z-20 h-11 w-11 items-center justify-center rounded-full border bg-white/80 shadow ${
              canScrollLeft ? "opacity-100" : "opacity-0 pointer-events-none"
            }`}
          >
            ‹
          </button>

          <button
            type="button"
            onClick={() => scrollByStep(1)}
            aria-label="Вправо"
            className={`hidden lg:flex absolute right-2 top-1/2 -translate-y-1/2 z-20 h-11 w-11 items-center justify-center rounded-full border bg-white/80 shadow ${
              canScrollRight ? "opacity-100" : "opacity-0 pointer-events-none"
            }`}
          >
            ›
          </button>

          <div className="hidden lg:block absolute -top-7 right-2 text-xs text-ash/70">
            Листайте вправо / влево или тяните мышью
          </div>

          <div
            ref={sliderRef}
            className="flex gap-6 overflow-x-auto px-4 lg:px-8 lg:cursor-grab snap-x snap-mandatory"
          >
            {visibleItems.map((item, index) => (
              <article
                key={`${item.title}-${item.material}`}
                className="min-w-[280px] snap-start overflow-hidden rounded-xl border bg-white shadow"
              >
                <button
                  type="button"
                  onClick={() => openLightbox(index)}
                  className="block w-full text-left"
                >
                  <img
                    src={item.image}
                    alt={item.title}
                    className="h-56 w-full object-cover"
                    draggable={false}
                  />
                  <div className="p-6">
                    <h3 className="font-medium">{item.title}</h3>
                    <p className="text-sm text-ash">{item.material}</p>
                  </div>
                </button>
              </article>
            ))}
          </div>
        </div>
      </motion.div>

      <Lightbox
        open={isLightboxOpen}
        close={() => closeLightbox()}
        index={lightboxIndex}
        slides={slides}
        plugins={[Fullscreen, Zoom]}
        carousel={{ finite: false }}
      />
    </section>
  );
}


